class Cache:
    def __init__(self): self.data = {}
    def put(self, key, value, now, ttl):
        if key not in self.data: self.data[key] = (value, now + ttl)
    def get(self, key, now):
        entry = self.data.get(key)
        if not entry or now > entry[1]: return None
        return entry[0] or None

